function EXTRA(R,ICON){
 /* hook: a clean and a smeared copy of the same pulse (five cosines; the smeared one delays each harmonic differently) */
 ICON.htClean=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${HT_box(0,0,380,160,{fill:'#FFFFFF',st:GRN,sw:3,r:18})}${HT_T(20,36,'weaker, later, same shape',{fs:24,fw:800,fill:GRN})}${HT_L(20,118,360,118,HT_GRY,2)}${HT_curve(t=>HT_pulse(t),-2.6,5.2,24,356,118,60,HT_GRY,3,200,HT_dash)}${HT_curve(t=>0.6*HT_pulse(t,1.6),-2.6,5.2,24,356,118,60,GRN,5,200)}</g>`;
 ICON.htSmear=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${HT_box(0,0,380,160,{fill:'#FFFFFF',st:MAG,sw:3,r:18})}${HT_T(20,36,'highs and lows arrive apart',{fs:24,fw:800,fill:MAG})}${HT_L(20,118,360,118,HT_GRY,2)}${HT_curve(t=>HT_pulse(t),-2.6,5.2,24,356,118,60,HT_GRY,3,200,HT_dash)}${HT_curve(t=>0.6*HT_pulse(t,0,0.32),-2.6,5.2,24,356,118,60,MAG,5,200)}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.htRc1=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${HT_L(0,120,420,120,HT_GRY,2)}${HT_curve(t=>HT_pulse(t),-2.6,5.2,0,420,120,60,HT_GRY,3,200,HT_dash)}${HT_curve(t=>1.3*HT_pulse(t,1.6),-2.6,5.2,0,420,120,60,BLU,5,200)}${HT_T(210,184,'same shape, later',{fs:24,fw:800,a:'middle',fill:BLU})}<rect x="0" y="210" width="210" height="96" fill="${RED}" fill-opacity=".10"/>${HT_L(0,290,420,290,HT_GRY,2)}${HT_curve(HT_sinc,-14,14,0,420,290,70,BLU,4,200)}${HT_T(10,328,'ideal: nonzero for t &lt; 0',{fs:24,fw:800,fill:RED})}</g>`;
 ICON.htRc2=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${HT_L(0,250,190,250,HT_GRY,2)}${HT_curve(HT_R,-2,2,0,190,250,720,BLU,5)}${HT_arrow(198,170,236,170,INK,4)}${HT_L(244,250,420,250,HT_GRY,2)}${HT_curve(HT_S,-10,10,244,420,250,720,ORG,5)}${HT_T(95,290,'Rₓ(τ)',{fs:26,fw:800,a:'middle',fill:BLU})}${HT_T(332,290,'|X(ω)|²',{fs:26,fw:800,a:'middle',fill:ORG})}${HT_T(210,40,'peak 0.25 = E at τ = 0',{fs:24,fw:800,a:'middle'})}</g>`;
 ICON.htRc3=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${HT_L(0,165,420,165,HT_GRY,2)}${HT_curve(t=>Math.cos(t),0,2*Math.PI,0,420,165,110,HT_GRY,4,200,HT_dash)}${HT_curve(t=>Math.sin(t),0,2*Math.PI,0,420,165,110,GRN,6,200)}${HT_T(210,320,'cos → sin: a quarter period later',{fs:24,fw:800,a:'middle',fill:GRN})}</g>`;
}
